-- 0086: تحديث نص قالب الاتفاقية والملحق (بلا ذكر الإدارة والقسم). المولّد tools/agreements/mk86.py
update public.agr_templates set body = $t${"agreement": [{"t": "p", "x": "بعون الله تعالى وتوفيقه، أُبرمت اتفاقية شراكة مجتمعية في محافظة الأحساء يوم ............ بتاريخ ..../..../{yh}هـ الموافق ..../..../{yg}م بين كل من:"}, {"t": "parties"}, {"t": "h", "x": "تمهيد", "plain": true}, {"t": "p", "x": "حيث إن للطرف الأول رغبة في تعزيز مساهمة رجال الأعمال{and_companies} في التنمية الصحية وفق رؤية المملكة 2030 وتمكينهم من تقديم الدعم في الخدمات الصحية، تحت إشراف تجمع الأحساء الصحي وفقاً للاحتياجات الفعلية للمستفيد بجودة وكفاءة عالية، وحيث إن الطرف الثاني يرغب في خدمة مجتمعه ووطنه، فقد اتفقت رغبة الطرفين على عقد اتفاقية تستثمر إمكانيات وقدرات كلا الطرفين بما يحقق التكامل وينفع المجتمع ويخدم المواطنين، من خلال قيام الطرف الثاني بالتبرع لإنشاء وتجهيز مركز رعاية صحية أولية متكاملة{land_phrase}{loc} بمحافظة الأحساء وفق المواد الواردة أدناه:"}, {"t": "h", "x": "", "v2x": "التمهيد والملاحق"}, {"t": "p", "x": "التمهيد أعلاه جزء لا يتجزأ من هذه الاتفاقية."}, {"t": "p", "if": "annex", "x": "ويُعد «ملحق إجراءات وآليات العمل» المرفق جزءاً مكملاً لهذه الاتفاقية، وعند التعارض تُقدَّم أحكام الاتفاقية."}, {"t": "h", "x": "التعريفات", "if": "v2"}, {"t": "p", "if": "v2", "x": "يُقصد بالكلمات والعبارات التالية أينما وردت في هذه الاتفاقية المعاني المبينة أمامها ما لم يقتض السياق غير ذلك:"}, {"t": "defs", "if": "v2", "items": [["المشروع", "إنشاء وتجهيز مركز الرعاية الصحية الأولية موضوع هذه الاتفاقية، بجميع مراحله من التصميم حتى الاستلام."], ["المركز", "مبنى مركز الرعاية الصحية الأولية الناتج عن المشروع بتجهيزاته."], ["المستفيد", "المكتب الهندسي أو المقاول أو المورد أو الجهة الخدمية المستحقة لأي دفعة من مبلغ التبرع."], ["الإفادة", "خطاب أو بريد رسمي من الطرف الأول يحدد مبلغ الدفعة ومستفيدها ومرفقاتها."], ["المنسق", "الشخص الذي يسميه كل طرف لتبادل المراسلات والمتابعة."], ["الملحق", "ملحق إجراءات وآليات العمل المرفق بهذه الاتفاقية."]]}, {"t": "h", "x": "موضوع الاتفاقية"}, {"t": "p", "x": "يسعى الطرفان بموجب هذه الاتفاقية إلى إنشاء وتجهيز مركز رعاية صحية أولية متكاملة بمحافظة الأحساء حسب المخططات والمواصفات المعتمدة لدى الطرف الأول."}, {"t": "h", "x": "سريان الاتفاقية ومدتها"}, {"t": "p", "x": "يلتزم الطرفان بتنفيذ الأعمال المتفق عليها خلال ({months}) شهراً ميلادياً تبدأ من تاريخ توقيع الاتفاقية، بعد عرضها على الجهة المختصة لدى الطرف الأول واعتماد الشروط الفنية المعتمدة لدى الطرف الأول."}, {"t": "h", "x": "التزامات الطرف الأول"}, {"t": "ol", "items": [{"x": "دعم وتسهيل الإجراءات النظامية اللازمة لإتمام أعمال المشروع."}, {"x": "تخصيص موقع مناسب لإنشاء مركز رعاية صحية أولية متكامل بمحافظة الأحساء.", "if": "!donor_land"}, {"x": "الاستفادة من الموقع المخصص لإنشاء مركز رعاية صحية أولية متكامل بمحافظة الأحساء.", "if": "donor_land"}, {"x": "تقديم الدعم اللازم لاستخراج كافة التراخيص اللازمة لتنفيذ أعمال المشروع."}, {"x": "تشغيل المرفق الصحي فور انتهاء أعمال المشروع."}, {"x": "تسمية المركز ({center}).", "if": "naming"}, {"x": "إدارة مرحلة الإعداد للمشروع من خلال اعتماد المكتب المصمم واستشاري المشروع والمقاول المنفذ والإشراف والمتابعة لأعمال المشروع بالكامل حسب الآليات والأنظمة والمواصفات المعتمدة لدى الطرف الأول."}, {"x": "يتم إبرام عقد تفصيلي لمرحلة التصميم وإعداد وثائق المشروع من رسومات ومواصفات وجداول كميات والإشراف على المشروع بين الطرف الأول والمكتب الاستشاري المعتمد والطرف الثاني."}, {"x": "اعتماد واختيار المقاولين والموردين المؤهلين لتنفيذ المشروع."}, {"x": "يتم إبرام عقد تفصيلي لتنفيذ المشروع بين الطرف الأول والمقاول المعتمد والطرف الثاني."}, {"x": "تقديم تقارير دورية عن سير الأعمال بالمشروع كل ربع سنوي ميلادي."}, {"x": "الالتزام بالتشغيل الكامل للمركز بالكادر الطبي والإداري واللوجستي وعمل الصيانة اللازمة لذلك بما يكفل استمرار عمل المركز بكامل طاقته الفنية والتشغيلية في جميع الأوقات."}, {"x": "التنسيق مع جميع الجهات الحكومية والتأكد من استدامة موقع المشروع وعدم تعرضه لأية معوقات."}]}, {"t": "h", "x": "التزامات الطرف الثاني"}, {"t": "ol", "items": [{"x": "تمويل المشروع بمبلغ وقدره ({amount_n}) ريال سعودي ({amount_w}) غير شاملة لضريبة القيمة المضافة، لإنشاء وتجهيز مركز رعاية صحية أولية متكاملة{loc} بمحافظة الأحساء، وتشمل هذه الميزانية البنود التالية:", "then": [{"t": "budget"}, {"t": "small", "x": "* تعتبر تكاليف البنود استرشادية وتقديرية."}]}, {"x": "سداد المستحقات المالية للمقاولين أو الموردين للمشروع مباشرة من الطرف الثاني وذلك بعد إفادة الطرف الأول بالإنجاز والصرف، ويكون التقييم الفني والمالي والتعاقدي وتحديد مبالغ الدفعات ومستفيديها وأوقات صرفها محل تقدير الطرف الأول."}]}, {"t": "h", "x": "بيانات المشروع"}, {"t": "pdata"}, {"t": "h", "x": "الخدمات المقدمة بالمركز (خدمات الرعاية الأولية)"}, {"t": "services"}, {"t": "h", "x": "سرية المعلومات"}, {"t": "p", "x": "يلتزم الطرفان بموجب هذه الاتفاقية بالحفاظ على سرية المعلومات والبيانات."}, {"t": "h", "x": "توجيه الإشعارات والمراسلات"}, {"t": "p", "x": "تتم المراسلات بين الطرفين بواسطة البريد الإلكتروني من قبل منسقيهما:"}, {"t": "notices"}, {"t": "h", "x": "حقوق الملكية"}, {"t": "p", "x": "يلتزم الطرفان بمراعاة حقوق الملكية الفكرية لكل طرف."}, {"t": "h", "x": "أحكام عامة"}, {"t": "ol", "items": [{"x": "يجوز للأطراف مجتمعين مراجعة هذه الاتفاقية لتعديلها أو تطويرها على نحو يخدم المصلحة العامة، وذلك بناءً على موافقة خطية من كليهما."}, {"x": "يلتزم الطرف الأول باتخاذ ما يلزم من الإجراءات لضمان تنفيذ أعمال المشروع وفقاً للأنظمة والتعليمات المعمول بها بأفضل السبل، حيث يعتبر الطرف الأول الجهة المعنية والمسؤولة بالكامل لتنفيذ المشروع وتشغيله حسب الاحتياج وبما يتوافق مع المعايير الفنية والصحية المعتمدة، ولا يتحمل الطرف الثاني أية مسؤولية تنتج عن أخطاء تنفيذية تتعلق بتشغيل المشروع وتصرفات كادره وأداء معداته."}, {"x": "يحق للطرف الأول التعديل والمناقلة بين بنود المشروع بما لا يتجاوز القيمة الإجمالية للاتفاقية المبرمة ويضمن تحقيق مصلحة المشروع."}]}, {"t": "h", "x": "الأنظمة المعمول بها", "v2x": "الأنظمة المعمول بها وتسوية الخلافات"}, {"t": "p", "x": "يتم تنفيذ هذه الاتفاقية وفقاً للأنظمة والقوانين المعمول بها في المملكة العربية السعودية."}, {"t": "p", "if": "v2", "x": "وفي حال نشوء أي خلاف حول تفسير هذه الاتفاقية أو تنفيذها يسعى الطرفان إلى حله ودياً خلال ثلاثين (30) يوماً من إشعار أحدهما للآخر كتابياً، فإن تعذر ذلك يُحال إلى الجهة المختصة في المملكة العربية السعودية."}, {"t": "h", "x": "أسباب انقضاء العقد", "v2x": "انقضاء الاتفاقية"}, {"t": "p", "if": "!v2", "x": "ينتهي العقد بسبب قوة قاهرة."}, {"t": "p", "if": "v2", "x": "تنقضي هذه الاتفاقية بتمام تنفيذ المشروع وتسليم المركز للطرف الأول، أو بسبب قوة قاهرة تحول دون تنفيذها، وعلى الطرف المتأثر إخطار الطرف الآخر كتابياً فور علمه بها، ولا يخل انقضاؤها بما استحق من التزامات قبل ذلك."}, {"t": "h", "x": "لغة ونسخ الاتفاقية"}, {"t": "p", "x": "حررت هذه الاتفاقية من نسختين باللغة العربية وتسلم كل طرف نسخة واحدة، وذلك للعمل بموجبها، وتوثيقاً لما تقدم فقد جرى التوقيع على هذه الاتفاقية في التاريخ المبين في مقدمتها."}, {"t": "end", "x": "والله الموفق،"}, {"t": "sig"}], "annex": [{"t": "lead", "x": "نشكر لكم مبادرتكم الكريمة بالتبرع لإنشاء وتجهيز {center_or}. أعددنا هذا الملحق لتكون الصورة كاملة أمامكم قبل البدء: من يعمل في المشروع، وكيف نتواصل، وكيف تُصرف المبالغ، ولماذا تكلفة المنشأة الصحية أعلى من المباني المعتادة، وكيف نضمن الجودة، وما الذي تحتاجونه منا ونحتاجه منكم في كل مرحلة."}, {"t": "note", "x": "هذا الملحق جزء مكمل للاتفاقية الموقعة بين الطرفين، يشرح آليات تنفيذها ولا يضيف التزامات مالية جديدة. وعند أي تعارض تُقدَّم أحكام الاتفاقية. المدد والنسب الواردة فيه تقريبية من واقع مشاريع التجمع المماثلة، ويُحدَّث المتبرع بالجدول الفعلي في التقارير الدورية."}, {"t": "kv", "rows": [["المشروع", "{center_or}"], ["الموقع", "{loc_or}"], ["مبلغ التبرع", "{amount_n} ريال سعودي ({amount_w}) غير شامل ضريبة القيمة المضافة"], ["مدة الاتفاقية", "{months} شهراً ميلادياً من تاريخ التوقيع"], ["مسطح البناء التقريبي", "{bua_t}"]]}, {"t": "h2", "x": "أطراف المشروع ودور كل طرف"}, {"t": "p", "x": "ينفَّذ المشروع بمنظومة متكاملة، لكل طرف فيها دور محدد. ويدير التجمع المشروع عبر جهته المختصة، ويكون منسقه جهة الاتصال الوحيدة للمتبرع في كل ما يخص المشروع."}, {"t": "tbl", "w": [22, 50, 28], "head": ["الطرف", "دوره في المشروع", "علاقته بالمتبرع"], "rows": [["المتبرع (الطرف الثاني)", "تمويل المشروع وسداد المستحقات للمستفيدين مباشرة بعد إفادة التجمع، والاطلاع على سير العمل عبر المنسق والتقارير الدورية.", "صاحب المبادرة والممول"], ["تجمع الأحساء الصحي (الطرف الأول)", "إدارة المشروع فنياً: اعتماد التصاميم والمواصفات، واختيار المكاتب والمقاولين والموردين، والإشراف والمتابعة، وتحديد الدفعات، والاستلام، ثم التشغيل والصيانة.", "جهة الاتصال الوحيدة"], ["المكتب الهندسي المصمم", "التصاميم المعمارية والإنشائية والكهروميكانيكية، وجداول الكميات والمواصفات، واستخراج رخصة البناء.", "عبر التجمع (عقد ثلاثي)"], ["الاستشاري المشرف", "الإشراف اليومي على التنفيذ، واعتماد المواد والأعمال، ومراجعة المستخلصات والتحقق من نسب الإنجاز.", "عبر التجمع"], ["المقاول الرئيسي", "تنفيذ أعمال البناء والتشطيب والأنظمة وفق المخططات والمواصفات المعتمدة.", "عبر التجمع (عقد ثلاثي)"], ["الموردون", "توريد وتركيب البنود الخارجة عن عقد المقاول، مثل الأثاث الطبي وغير الطبي وبعض الأنظمة.", "عبر التجمع"], ["الجهات الخدمية والرقابية", "الشركة السعودية للكهرباء، وشركة المياه، والاتصالات، والبلدية، والدفاع المدني — التراخيص وإيصال الخدمات والفسوحات.", "يتابعها التجمع"]]}, {"t": "h2", "x": "التواصل والحوكمة"}, {"t": "h3", "x": "قنوات التواصل"}, {"t": "ul", "items": [{"x": "يحدد كل طرف منسقاً واحداً، وتتم المراسلات الرسمية بالبريد الإلكتروني بين المنسقَين (المادة التاسعة من الاتفاقية)."}, {"x": "اجتماع دوري شهري بين الطرفين لاستعراض التقدم والقرارات المطلوبة والدفعات القادمة، يُوثَّق بمحضر."}, {"x": "تقرير دوري كل ربع سنة ميلادي يرسله التجمع للمتبرع: نسبة الإنجاز، والصور، والمبالغ المصروفة والمتوقعة، والمخاطر وطريقة معالجتها."}, {"x": "زيارات ميدانية للموقع متاحة للمتبرع أو من يمثله بالتنسيق المسبق مع منسق التجمع، وبالالتزام باشتراطات السلامة في الموقع."}]}, {"t": "note", "kind": "warn", "x": "متابعة المشروع وأي توجيه للمكتب أو المقاول أو المورد تتم من خلال إدارة التجمع فقط. التوجيه المباشر من غير الجهة المشرفة يربك التنفيذ وقد يترتب عليه أثر مالي أو زمني لا يحتسبه العقد."}, {"t": "h3", "x": "من يقرر ماذا"}, {"t": "matrix", "head": ["القرار", "تجمع الأحساء الصحي", "المتبرع"], "rows": [["اعتماد التصاميم والمواصفات", "يعتمد", "—"], ["اختيار المقاولين والموردين", "يقيّم ويختار ويعتمد", "يُبلَّغ بالنتيجة"], ["اعتماد المواد والعينات", "يعتمد عبر الاستشاري", "—"], ["تحديد مبالغ الدفعات ومستفيديها وأوقاتها", "يحدد", "يسدد مباشرة للمستفيد"], ["التعديل والمناقلة بين البنود", "يقرر في حدود القيمة الإجمالية", "يُبلَّغ كتابياً"], ["أي زيادة على القيمة الإجمالية", "يقترح ويبرر", "تعديل خطي للاتفاقية بين الطرفين"], ["التشغيل والصيانة بعد التسليم", "مسؤولية كاملة", "—"]]}, {"t": "h2", "x": "رحلة المشروع: من التوقيع إلى الافتتاح"}, {"t": "p", "x": "تمر رحلة المشروع بالمراحل التالية خلال مدة الاتفاقية ({months} شهراً). بعض المراحل تسير بالتوازي، والمدد تقريبية تتأثر بسرعة الاعتمادات وإجراءات الجهات الخدمية."}, {"t": "phases"}, {"t": "note", "x": "أكثر ما يؤخر المشاريع عادة: إجراءات إيصال الكهرباء، وتأخر السداد. لذلك نبدأ إجراءات الخدمات مبكراً، ونرسل جدول الدفعات المتوقع مسبقاً."}, {"t": "h2", "x": "التمويل وآلية صرف المستحقات"}, {"t": "p", "x": "لا يستلم التجمع أي مبالغ. يسدد المتبرع مستحقات المقاولين والموردين والمكاتب مباشرة لحساباتهم، بعد أن يفيده التجمع بالإنجاز والصرف (المادة الخامسة من الاتفاقية)."}, {"t": "steps", "items": ["يعدّ التجمع ملخصاً بمبالغ وأوقات الدفعات التقديرية المطلوب سدادها للمقاولين والموردين، ويحدّثه مع المتبرع بشكل دوري.", "يراجع الاستشاري مستخلص المقاول ويتحقق من نسبة الإنجاز في الموقع، ثم يعتمده التجمع.", "يرفع التجمع الدفعة كل أسبوعين (دفعتان في الشهر) بإفادة رسمية تحدد المبلغ والمستفيد وبيانات حسابه، ومعها المستخلص المعتمد والفاتورة الضريبية.", "يصرف المتبرع الدفعة خلال أسبوع واحد من تاريخ الرفع، ويرسل ما يثبت التحويل للمنسق.", "لا تتجاوز قيمة الدفعة الواحدة 20% من إجمالي مبلغ التبرع."]}, {"t": "h3", "x": "متى يُصرف كل بند تقريباً"}, {"t": "cash"}, {"t": "costbox"}, {"t": "h2", "x": "لماذا تكلفة المركز الصحي أعلى من المباني المعتادة؟"}, {"t": "p", "x": "يتفاجأ كثير من المتبرعين بأسعار المواد والأنظمة مقارنة بأسعار السوق للمباني السكنية والتجارية. والسبب أن المركز الصحي منشأة حرجة: يستقبل المرضى، ويحتوي أنظمة طبية وأنظمة سلامة لا توجد في المباني المعتادة، وتخضع لاشتراطات وزارة الصحة والدفاع المدني وكود البناء السعودي، ويُتوقع أن يعمل عقوداً بأقل صيانة ممكنة."}, {"t": "tbl", "w": [24, 38, 38], 